// SetEventCollectionMode Set the event collection mode.
//
// Set the event collection mode for a context. The mode
// controls the event collection behavior of all events in event
// groups created in the context. This API is invalid in kernel
// replay mode.
//
// Starting with CUDA 13.0, this function is unsupported and should not be used. It always returns the error code [ErrLegacyProfilerNotSupported].
//
//   - context: The context
//   - mode: The event collection mode
//
// Returns:
//   - [Success]
//   - [ErrNotInitialized]
//   - [ErrInvalidContext]
//   - [ErrInvalidOperation]: if called when replay mode is enabled
//   - [ErrNotSupported]: if mode is not supported on the device
//
// Wraps cuptiSetEventCollectionMode.
func SetEventCollectionMode(context Context, mode EventCollectionMode) error {
	if err := checkLibSym("cuptiSetEventCollectionMode"); err != nil {
		return err
	}
	return toError(fnSetEventCollectionMode(context, mode))
}

// SetThreadIdType Set the thread-id type.
//
// CUPTI uses the method corresponding to set type to generate the thread-id. See enum [ActivityThreadIdType] for the list of methods. Activity records having thread-id field contain the same value. Thread id type must not be changed during the profiling session to avoid thread-id value mismatch across activity records. This API is not supported when multiple subscribers are allowed. Use the corresponding attribute instead: [ActivityAttrThreadIdType]
//
// Returns:
//   - [ErrNotSupported]: if type is not supported on the platform
//
// Wraps cuptiSetThreadIdType.
func SetThreadIdType(type_ ActivityThreadIdType) error {
	if err := checkLibSym("cuptiSetThreadIdType"); err != nil {
		return err
	}
	return toError(fnSetThreadIdType(type_))
}

// Subscribe Initialize a callback subscriber with a callback function and user data.
//
// Initializes a callback subscriber with a callback function and (optionally) a pointer to user data. The returned subscriber handle can be used to enable and disable the callback for specific domains and callback IDs. Note Only a single subscriber can be registered at a time. To ensure that no other CUPTI client interrupts the profiling session, it’s the responsibility of all the CUPTI clients to call this function before starting the profling session. In case profiling session is already started by another CUPTI client, this function returns the error code [ErrMultipleSubscribersNotSupported]. Note that this function returns the same error when application is launched using NVIDIA tools like Nsight Systems, Nsight Compute, cuda-gdb and cuda-memcheck. Note This function does not enable any callbacks. Note Thread-safety: this function is thread safe. Note While this API is fully supported and remains available, we recommend transitioning to the new API [SubscribeV2] moving forward.
//
//   - callback: The callback function (see [CallbackFunc])
//   - userdata: A pointer to user data. This data will be passed to the callback function via the userdata parameter
//
// Returns:
//   - [ErrInvalidParameter]: if subscriber is NULL
//   - [ErrMultipleSubscribersNotSupported]: if there is already a CUPTI subscriber, or if the application is launched with NVIDIA tools like Nsight Systems, Nsight Compute, cuda-gdb and cuda-memcheck.
//   - [ErrNotInitialized]: if unable to initialize CUPTI
//   - [Success]: on success
//
// Wraps cuptiSubscribe.
func Subscribe(callback uintptr, userdata uintptr) (Subscriber, error) {
	if err := checkLibSym("cuptiSubscribe"); err != nil {
		var zero Subscriber
		return zero, err
	}
	var out Subscriber
	if err := toError(fnSubscribe(&out, callback, userdata)); err != nil {
		var zero Subscriber
		return zero, err
	}
	return out, nil
}

// SubscribeV2 Initialize a callback subscriber with a callback function and user data.
//
// Initializes a callback subscriber with a callback function and (optionally) a pointer to user data. The returned subscriber handle can be used to enable and disable the callback for specific domains and callback IDs. Note Only a single subscriber can be registered at a time. To ensure that no other CUPTI client interrupts the profiling session, it’s the responsibility of all the CUPTI clients to call this function before starting the profling session. In case profiling session is already started by another CUPTI client, this function returns the error code [ErrMultipleSubscribersNotSupported]. Note that this function returns the same error when application is launched using NVIDIA tools like Nsight Systems, Nsight Compute, cuda-gdb and cuda-memcheck. Note This function does not enable any callbacks. Note Thread-safety: this function is thread safe.
//
//   - callback: The callback function (see [CallbackFunc])
//   - userdata: A pointer to user data. This data will be passed to the callback function via the userdata parameter
//   - pParams: A pointer to [SubscriberParams]. Can be NULL
//
// Returns:
//   - [ErrInvalidParameter]: if:pParams.structSize is not filled with the size of the structure
//   - [ErrMultipleSubscribersNotSupported]: if there is already a CUPTI subscriber, or if the application is launched with NVIDIA tools like Nsight Systems, Nsight Compute, cuda-gdb and cuda-memcheck.
//   - [ErrNotInitialized]: if unable to initialize CUPTI
//   - [Success]: on success
//
// Wraps cuptiSubscribe_v2.
func SubscribeV2(callback uintptr, userdata uintptr, pParams *SubscriberParams) (Subscriber, error) {
	if err := checkLibSym("cuptiSubscribe_v2"); err != nil {
		var zero Subscriber
		return zero, err
	}
	var out Subscriber
	if err := toError(fnSubscribeV2(&out, callback, userdata, pParams)); err != nil {
		var zero Subscriber
		return zero, err
	}
	return out, nil
}

// SupportedDomains Get the available callback domains.
//
// Returns in *domainTable an array of size *domainCount of all the available callback domains. Note Thread-safety: this function is thread safe.
//
// Returns:
//   - [ErrInvalidParameter]: if domainCount or domainTable are NULL
//   - [ErrNotInitialized]: if unable to initialize CUPTI
//   - [Success]: on success
//
// Wraps cuptiSupportedDomains.
func SupportedDomains() (domainCount uint, domainTable uintptr, err error) {
	if err := checkLibSym("cuptiSupportedDomains"); err != nil {
		return 0, 0, err
	}
	var out0 uint
	var out1 uintptr
	if err := toError(fnSupportedDomains(&out0, &out1)); err != nil {
		return 0, 0, err
	}
	return out0, out1, nil
}

// unsubscribe Unregister a callback subscriber.
//
// Removes a callback subscriber so that no future callbacks will be issued to that subscriber. Note Thread-safety: this function is thread safe.
//
//   - subscriber: Handle to the initialize subscriber
//
// Returns:
//   - [ErrInvalidParameter]: if subscriber is NULL or not initialized
//   - [ErrNotInitialized]: if unable to initialized CUPTI
//   - [Success]: on success
//
// Wraps cuptiUnsubscribe.
func unsubscribe(subscriber Subscriber) error {
	if err := checkLibSym("cuptiUnsubscribe"); err != nil {
		return err
	}
	return toError(fnunsubscribe(subscriber))
}
